import base64
import string

def is_base64(s):
    try:
        return base64.b64decode(s, validate=True)
    except Exception:
        return None

def analyze_decoded(filename):
    with open(filename, 'r') as f:
        data = f.read()

    print(f"Decoded length: {len(data)} bytes")

    # Check if content is printable
    printable_ratio = sum(c in string.printable for c in data) / len(data)
    print(f"Printable character ratio: {printable_ratio*100:.2f}%")

    # Check for recurring patterns
    chunks = [data[i:i+4] for i in range(0, len(data)-4, 4)]
    pattern_count = {}
    for chunk in chunks:
        pattern_count[chunk] = pattern_count.get(chunk, 0) + 1

    print("\nMost common 4-byte patterns:")
    for pattern, count in sorted(pattern_count.items(), key=lambda x: x[1], reverse=True)[:10]:
        if count > 1:
            print(f"'{pattern}': {count} times")

    # Try base64 decoding chunks
    chunks = [data[i:i+100] for i in range(0, len(data), 100)]
    for i, chunk in enumerate(chunks[:5]):
        b64_result = is_base64(chunk)
        if b64_result:
            print(f"\nChunk {i} appears to be base64. First 50 bytes:")
            print(b64_result[:50])

