from collections import Counter
import struct

def analyze_file(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    # Total length
    print(f"Total file size: {len(data)} bytes")

    # Check divisibility
    print("\nPossible block sizes (divisors):")
    for i in range(2, 101):
        if len(data) % i == 0:
            print(f"{i} ", end='')

    # Frequency analysis
    print("\n\nByte frequency analysis (top 20):")
    freq = Counter(data)
    for byte, count in freq.most_common(20):
        print(f"0x{byte:02x}: {count} times ({count/len(data)*100:.2f}%)")

    # Look for patterns
    print("\nChecking for repeating patterns...")
    for pattern_len in range(2, 9):
        patterns = {}
        for i in range(len(data) - pattern_len):
            pattern = data[i:i+pattern_len]
            if pattern in patterns:
                patterns[pattern] += 1
            else:
                patterns[pattern] = 1

        # Show patterns that appear more than 3 times
        frequent_patterns = {k: v for k, v in patterns.items() if v > 3}
        if frequent_patterns:
            print(f"\nRepeating {pattern_len}-byte patterns:")
            for pattern, count in sorted(frequent_patterns.items(), key=lambda x: x[1], reverse=True)[:5]:
                print(f"Pattern {pattern.hex()}: appears {count} times")

    # Try to interpret as floating points
    print("\nTrying to interpret as floating points...")
    if len(data) % 4 == 0:
        floats = []
        for i in range(0, min(len(data), 40), 4):
            try:
                value = struct.unpack('f', data[i:i+4])[0]
                floats.append(value)
            except:
                pass
        if floats:
            print("First 10 values as floats:", floats[:10])

