import struct
import numpy as np

def get_mantissa_bits(float_val):
    bits = ''.join(format(b, '08b') for b in struct.pack('!f', float_val))
    return bits[9:]  # Get only mantissa bits

def try_ascii_from_mantissa(mantissa):
    # Try to convert groups of 8 bits to ASCII
    chars = []
    for i in range(0, len(mantissa)-7, 8):
        try:
            char = chr(int(mantissa[i:i+8], 2))
            if 32 <= ord(char) <= 126:  # printable ASCII
                chars.append(char)
        except:
            continue
    return ''.join(chars)

def read_floats(filename):
    floats = []
    with open(filename, 'rb') as f:
        while True:
            chunk = f.read(4)
            if not chunk or len(chunk) < 4:
                break
            float_val = struct.unpack('f', chunk)[0]
            floats.append(float_val)
    return floats

