import struct

def read_bytes_as_text(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    # Try different rolling window sizes
    for window in range(4, 50):
        for i in range(len(data) - window):
            chunk = data[i:i+window]
            try:
                text = chunk.decode('ascii')
                if 'csaw' in text.lower() or 'csawctf{' in text.lower():
                    print(f"Found potential flag fragment at offset {i}, window {window}: {text}")
            except:
                continue

    # Try looking at every 4 bytes
    for i in range(0, len(data)-4, 4):
        try:
            # Try both float and direct byte interpretations
            float_val = struct.unpack('f', data[i:i+4])[0]
            if abs(float_val) < 1000:  # Filter out extreme values
                as_int = int(float_val)
                if 32 <= as_int <= 126:
                    print(f"Float at {i} converts to ASCII: {chr(as_int)}")

            # Direct bytes to ASCII
            for j in range(4):
                byte = data[i+j]
                if 32 <= byte <= 126:
                    print(f"Direct byte at {i+j}: {chr(byte)}")
        except:
            continue

