import struct
import binascii

def analyze_float_patterns(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    # Store sequences of ASCII characters found
    ascii_sequences = []
    current_sequence = ""

    # Analyze as 32-bit floats
    for i in range(0, len(data)-3, 4):
        chunk = data[i:i+4]
        try:
            # Try interpreting as float
            float_val = struct.unpack('f', chunk)[0]

            # Convert to string representation
            float_str = str(float_val)

            # Check for printable ASCII in raw bytes
            for b in chunk:
                if 32 <= b <= 126:
                    char = chr(b)
                    if char.isalnum() or char in '{}_':
                        current_sequence += char
                    else:
                        if len(current_sequence) > 3:  # Only keep sequences of 4+ chars
                            ascii_sequences.append(current_sequence)
                        current_sequence = ""

            # Also check if the float value itself is in ASCII range
            if 32 <= abs(float_val) <= 126:
                try:
                    char = chr(int(abs(float_val)))
                    print(f"Float value {float_val} could represent ASCII '{char}'")
                except:
                    pass

        except:
            continue

        # Look for potential flag markers in hex representation
        try:
            hex_val = binascii.hexlify(chunk).decode()
            if 'csaw' in hex_val.lower() or 'ctf' in hex_val.lower():
                print(f"Potential flag marker in hex at offset {i}: {hex_val}")
        except:
            continue

    # Print found ASCII sequences
    print("\nFound ASCII sequences:")
    for seq in ascii_sequences:
        if len(seq) > 3:  # Only show longer sequences
            print(seq)

    # Try bit shifting patterns
    print("\nAnalyzing bit patterns...")
    for i in range(0, len(data)-7, 4):
        chunk = data[i:i+8]
        try:
            # Try different bit shifts
            for shift in range(8):
                value = int.from_bytes(chunk, 'big') >> shift
                try:
                    text = bytes.fromhex(hex(value)[2:]).decode('ascii')
                    if any(c.isalnum() for c in text):
                        print(f"Shifted {shift} bits at offset {i}: {text}")
                except:
                    continue
        except:
